24	    // Track seen user inbox items to fire turn-start only once per prompt
25	    const seenUserMessages = new Set<string>();
26	    // Track the current session ID for this location (events are server-wide)
27	    let currentSessionID: string | null = null;
28	    // Whether a turn-start has fired without its turn-end yet (guards the
29	    // several V2 idle signals so turn-end fires exactly once per turn)
30	    let turnActive = false;
31	    // Track the model used by the most recent assistant step
32	    let currentModel: string | null = null;
33	    // One-time model-context injection captured from the turn-start hook's
34	    // stdout, applied on the next LLM call via the session "context" hook.
35	    let pendingInjection: string | null = null;
