79	    function callHookSync(hookName: string, payload: Record<string, unknown>) {
80	      try {
81	        const json = JSON.stringify(payload);
82	        const [cmd, ...args] = hookCmd(hookName);
83	        spawnSync(cmd, args, {
84	          cwd: directory,
85	          input: json + "\n",
86	          stdio: ["pipe", "ignore", "ignore"],
