112	    // fireTurnStart fires turn-start synchronously (state must be ready before
113	    // mid-turn commits) and stashes any model-context injection emitted on stdout
114	    // for the session "context" hook to apply. Entire emits the injection at most
115	    // once per session, so pendingInjection is set on the first turn only.
116	    function fireTurnStart(payload: Record<string, unknown>) {
117	      turnActive = true;
118	      try {
119	        const json = JSON.stringify(payload);
120	        const [cmd, ...args] = hookCmd("turn-start");
121	        const proc = spawnSync(cmd, args, {
122	          cwd: directory,
123	          input: json + "\n",
124	          encoding: "utf8",
125	          stdio: ["pipe", "pipe", "ignore"],
126	        });
127	        const out = typeof proc.stdout === "string" ? proc.stdout : "";
