135	    function resetSessionTracking(sessionID: string) {
136	      if (currentSessionID === sessionID) {
137	        return false;
138	      }
139	      seenUserMessages.clear();
140	      currentModel = null;
141	      turnActive = false;
142	      currentSessionID = sessionID;
143	      // Drop any turn-start injection captured for the prior session so it
144	      // can't leak into the new session's system prompt.
145	      pendingInjection = null;
146	      return true;
147	    }
148	
149	    // Apply the one-time Entire context injection captured at turn-start by
150	    // appending it to the system prompt for this LLM call.
151	    // (V1: experimental.chat.system.transform)
152	    await ctx.session.hook("context", (event) => {
153	      if (pendingInjection && Array.isArray(event.system)) {
154	        event.system.push({ type: "text", text: pendingInjection });
