179	      // locations. Events without a location are guarded by sessionID below.
180	      const eventDirectory = event.location?.directory;
181	      if (eventDirectory !== undefined && eventDirectory !== directory) return;
182	      const data = event.data ?? {};
183	      const sessionID: string | undefined = data.sessionID;
184	
185	      switch (event.type) {
186	        // (V1: session.created) Start tracking a newly created session.
187	        case "session.created": {
188	          if (!sessionID) break;
189	          // Reset per-session tracking state when switching sessions.
190	          if (resetSessionTracking(sessionID)) {
191	            await callHook("session-start", {
192	              session_id: sessionID,
193	            });
194	          }
195	          break;
196	        }
197	
198	        // (V1: message.part.updated on the first user text part) The prompt
199	        // entering the session inbox is the earliest signal that carries the
200	        // prompt text, and it arrives before the first LLM call.
201	        case "session.inbox.enqueued": {
202	          if (!sessionID) break;
203	          if (resetSessionTracking(sessionID)) {
204	            callHookSync("session-start", {
205	              session_id: sessionID,
206	            });
207	          }
208	          const item = data.item;
209	          if (item?.type === "user" && data.inboxID && !seenUserMessages.has(data.inboxID)) {
210	            seenUserMessages.add(data.inboxID);
211	            fireTurnStart({
212	              session_id: sessionID,
213	              prompt: typeof item.payload?.text === "string" ? item.payload.text : "",
214	              model: currentModel ?? "",
215	            });
216	          }
217	          break;
218	        }
219	
220	        // (V1 fallback: message.updated on the user message itself) If the
221	        // enqueued event was missed, fall back to the delivered event and
222	        // fetch the prompt text through the session context.
223	        case "session.inbox.delivered": {
224	          if (!sessionID || !data.inboxID || seenUserMessages.has(data.inboxID)) break;
225	          seenUserMessages.add(data.inboxID);
226	          if (resetSessionTracking(sessionID)) {
227	            callHookSync("session-start", {
228	              session_id: sessionID,
229	            });
230	          }
231	          let prompt = "";
232	          try {
233	            const messages: unknown = await ctx.session.context({ sessionID });
