245	        }
246	
247	        // Track the model used by the most recent assistant step
248	        // (V1: message.updated on assistant messages' modelID)
249	        case "session.step.started": {
250	          const model = data.model;
251	          if (model?.id) currentModel = String(model.id);
252	          break;
253	        }
254	
255	        // (V1: session.status idle) A finished execution ends the turn. Some
256	        // flows surface other idle signals instead, so the session.status and
257	        // session.idle cases below act as fallbacks; turnActive guards them
