259	        case "session.execution.succeeded":
260	        case "session.execution.failed":
261	        case "session.execution.interrupted": {
262	          if (!sessionID || sessionID !== currentSessionID || !turnActive) break;
263	          turnActive = false;
264	          callHookSync("turn-end", {
265	            session_id: sessionID,
266	            model: currentModel ?? "",
267	          });
268	          break;
269	        }
270	
271	        // Idle fallbacks. session.status carries {status: {type: "idle"|"busy"|…}}
