273	        case "session.status":
274	        case "session.idle": {
275	          if (event.type === "session.status" && data.status?.type !== "idle") break;
276	          if (!sessionID || sessionID !== currentSessionID || !turnActive) break;
277	          turnActive = false;
278	          callHookSync("turn-end", {
279	            session_id: sessionID,
280	            model: currentModel ?? "",
281	          });
282	          break;
283	        }
