285	        case "session.compacted": {
286	          if (!sessionID) break;
287	          await callHook("compaction", {
288	            session_id: sessionID,
289	          });
290	          break;
291	        }
292	
293	        case "session.deleted": {
294	          if (!sessionID) break;
295	          // Use sync variant: session-end may fire during shutdown.
296	          callHookSync("session-end", {
297	            session_id: sessionID,
298	          });
299	          if (sessionID === currentSessionID) {
300	            seenUserMessages.clear();
301	            currentSessionID = null;
302	            turnActive = false;
303	            currentModel = null;
304	            pendingInjection = null;
305	          }
306	          break;
307	        }
308	
309	        // (V1: server.instance.disposed) Fires when this location shuts down
310	        // (e.g. `opencode run` exit) or the whole server disposes — the only
311	        // reliable way to end sessions on exit, since session.deleted fires
312	        // only on explicit user deletion.
313	        case "location.shutdown":
314	        case "global.disposed": {
315	          // location.shutdown fires for every hosted location; only this one's
316	          // teardown should end this plugin's tracked session.
317	          if (event.type === "location.shutdown" && eventDirectory !== directory) break;
318	          if (!currentSessionID) break;
319	          const ended = currentSessionID;
320	          seenUserMessages.clear();
321	          currentSessionID = null;
322	          turnActive = false;
323	          currentModel = null;
324	          pendingInjection = null;
325	          // Use sync variant: this is the last event before teardown.
326	          callHookSync("session-end", {
327	            session_id: ended,
328	          });
329	          break;
330	        }
331	      }
332	    }
333	
334	    // (V1: the returned dispose hook) Abort the event subscription on unload.
335	    return () => {
336	      controller.abort();
337	    };
