  "name": "opencode-entire-plugin",
  "version": "1.0.0",
  "description": "Unofficial patched version of Entire's OpenCode integration.",
  "homepage": "https://github.com/KuzniAI/opencode-entire-plugin#readme",
  "bugs": {
    "url": "https://github.com/KuzniAI/opencode-entire-plugin/issues"
  },
  "license": "MIT",
  "author": "KuźnAI",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/KuzniAI/opencode-entire-plugin.git"
  },
  "type": "module",
  "exports": {
    ".": "./src/entire.ts"
  },
  "scripts": {
    "format": "oxfmt",
    "format:check": "oxfmt --check",
    "lint": "oxlint",
    "lint:fix": "oxlint --fix",
    "typecheck": "tsc --noEmit"
  },
  "dependencies": {
    "@opencode/plugin": "^2.0.19"
  },
  "devDependencies": {
    "@types/node": "^26.6.3",
    "oxfmt": "^0.71.0",
    "oxlint": "^1.86.0",
    "typescript": "^7.0.2"
  }
}

